fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();
    
    // Create the first output matrix
    let mut x_grid = vec![vec![0.0; cols]; rows];
    // Create the second output matrix
    let mut y_grid = vec![vec![0.0; cols]; rows];

    for i in 0..rows {
        for j in 0..cols {
            x_grid[i][j] = x[j]; // Fill x_grid with elements from x
            y_grid[i][j] = y[i]; // Fill y_grid with elements from y
        }
    }

    (x_grid, y_grid)
}